      "concern_id": "C21",
      "effect": "moves",
      "direction": "toward local governments",
      "quote": "Each city sets the number of homes allowed on each residential lot and its own approval process.",
      "mechanism": "Transfers the authority to dictate residential density and approval steps from the state back to individual cities.",
      "certainty": "stated"
